import { TestBed } from '@angular/core/testing';
import { WatchlistStore } from '../app/watchlist-store';
import { Watchlist } from '../app/watchlist/watchlist';
import type { TmdbMovie } from '../app/movie';

function movie(id: number, title: string): TmdbMovie {
  return {
    id,
    title,
    release_date: '2024-05-01',
    poster_path: null,
    overview: 'Test movie',
  };
}

describe('watchlist', () => {
  beforeEach(() => {
    localStorage.clear();
    TestBed.configureTestingModule({ providers: [WatchlistStore] });
  });

  it('shows unwatched movies before watched movies', () => {
    const fixture = TestBed.createComponent(Watchlist);
    const component = fixture.componentInstance;
    const store = TestBed.inject(WatchlistStore);

    store.add(movie(1, 'Watched one'));
    store.add(movie(2, 'Unwatched two'));
    store.add(movie(3, 'Watched three'));
    store.add(movie(4, 'Unwatched four'));

    store.toggleWatched(1);
    store.toggleWatched(3);

    fixture.detectChanges();

    expect(component.movies().map((m) => m.id)).toEqual([2, 4, 1, 3]);

    // Reactivity: marking an unwatched movie as watched moves it behind the remaining unwatched ones.
    store.toggleWatched(2);
    expect(component.movies().map((m) => m.id)).toEqual([4, 1, 2, 3]);

    // And marking it unwatched again moves it back to the front group, stable within it.
    store.toggleWatched(2);
    expect(component.movies().map((m) => m.id)).toEqual([2, 4, 1, 3]);
  });

  it('keeps every store item in the list, just reordered', () => {
    const fixture = TestBed.createComponent(Watchlist);
    const component = fixture.componentInstance;
    const store = TestBed.inject(WatchlistStore);

    store.add(movie(10, 'A'));
    store.add(movie(11, 'B'));
    store.toggleWatched(10);

    const ids = component.movies().map((m) => m.id).sort((a, b) => a - b);
    expect(ids).toEqual([10, 11]);
    expect(component.movies().map((m) => m.id)).toEqual([11, 10]);
  });
});
```

