import { TestBed } from '@angular/core/testing';
import { WatchlistStore } from '../app/watchlist-store';
import { Watchlist } from '../app/watchlist/watchlist';
import { TmdbMovie } from '../app/movie';

function movie(id: number, title: string): TmdbMovie {
  return {
    id,
    title,
    release_date: '2024-05-01',
    poster_path: null,
    overview: 'Acceptance test movie',
  };
}

describe('watchlist', () => {
  beforeEach(() => {
    localStorage.clear();
    TestBed.resetTestingModule();
    TestBed.configureTestingModule({ providers: [WatchlistStore] });
  });

  it('lists unwatched movies before watched movies', () => {
    const fixture = TestBed.createComponent(Watchlist);
    const component = fixture.componentInstance;

    component.store.add(movie(1, 'Watched one'));
    component.store.add(movie(2, 'Unwatched two'));
    component.store.add(movie(3, 'Watched three'));
    component.store.add(movie(4, 'Unwatched four'));

    component.store.toggleWatched(1);
    component.store.toggleWatched(3);

    fixture.detectChanges();

    const ids = component.movies().map((m) => m.id);
    expect(ids).toEqual([2, 4, 1, 3]);

    // The rendered list follows the same order.
    const text = fixture.nativeElement.textContent;
    expect(text.indexOf('Unwatched four')).toBeGreaterThan(-1);
    expect(text.indexOf('Unwatched two')).toBeGreaterThan(text.indexOf('Watched one'));
    expect(text.indexOf('Unwatched four')).toBeGreaterThan(text.indexOf('Watched three'));

    // Toggling re-orders the list immediately.
    component.store.toggleWatched(2);
    expect(component.movies().map((m) => m.id)).toEqual([4, 1, 2, 3]);

    component.store.toggleWatched(2);
    expect(component.movies().map((m) => m.id)).toEqual([2, 4, 1, 3]);
  });

  it('still shows every item, only reordered', () => {
    const fixture = TestBed.createComponent(Watchlist);
    const component = fixture.componentInstance;

    component.store.add(movie(10, 'Alpha'));
    component.store.add(movie(11, 'Beta'));
    component.store.toggleWatched(10);

    const ids = component.movies().map((m) => m.id).sort((a, b) => a - b);
    expect(ids).toEqual([10, 11]);
    expect(component.movies().map((m) => m.id)).toEqual([11, 10]);
  });
});
```

