  // of the store's items: the store's order is kept within each group and no
  // item is added, dropped or duplicated. Being a computed signal it re-evaluates
  // as soon as the store's watched flags change.
  movies = computed(() => {
    const items = this.store.items()
    const unwatched = items.filter(movie => !movie.watched)
