import { Component, computed, inject, signal } from '@angular/core';
import { RouterLink } from '@angular/router';
import { WatchItem } from '../movie';
import { WatchlistStore } from '../watchlist-store';

@Component({
  imports: [RouterLink],
  selector: 'app-watchlist',
  styleUrl: './watchlist.scss',
  templateUrl: './watchlist.html',
})
export class Watchlist {
  store = inject(WatchlistStore)

  // Unwatched movies first, then watched ones, preserving the store's order
  // within each group. Derived from the store, so toggling watched regroups
  // the list reactively without ever adding, dropping or duplicating items.
  movies = computed(() => {
    const items = this.store.items();
    return [...items.filter(item => !item.watched), ...items.filter(item => item.watched)];
  })

